-- ds_recon_status (bar by status, plus a counter for the total)
SELECT recon_status, count(*) AS records FROM northbridge.lakeflow.gold_reconciliation GROUP BY recon_status;

-- ds_recon_trend (line or stacked bar by day and status)
SELECT date_add(DATE'2024-01-01', day - 1) AS txn_date, recon_status, count(*) AS records
FROM northbridge.lakeflow.gold_reconciliation GROUP BY 1, 2 ORDER BY 1;

-- ds_recon_detail (table: the 50 largest amount mismatches)
SELECT txn_id, date_add(DATE'2024-01-01', day - 1) AS txn_date,
       gateway_amount, ledger_amount, amount_diff
FROM northbridge.lakeflow.gold_reconciliation
WHERE recon_status = 'AMOUNT_MISMATCH' ORDER BY abs(amount_diff) DESC LIMIT 50;
